require_once dirname(__DIR__).'/src/Services/ApiService.php';
try{require_disposable_test_profile();}catch(Throwable $e){fwrite(STDERR,"REFUSED: ".$e->getMessage()."\n");exit(2);}
$base=rtrim($argv[1]??'','/');if($base===''||!in_array(strtolower((string)parse_url($base,PHP_URL_HOST)),['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: marker-check tests require loopback API.\n");exit(2);}
if(!getenv('TRAILWATCH_TEST_SESSION_COOKIE')||!getenv('TRAILWATCH_TEST_CSRF_TOKEN')){fwrite(STDERR,"REFUSED: scratch operator cookie and CSRF token are required.\n");exit(2);}
function marker_assert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);echo "PASS $message\n";}
function marker_call(string $method,string $path,?array $payload=null,bool $auth=true,bool $csrf=true):array{$headers="Content-Type: application/json\r\n".($auth?"Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\n":'').($csrf?"X-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n":'');$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);$raw=@file_get_contents($GLOBALS['base'].$path,false,$ctx);$status=(int)substr($http_response_header[0]??'HTTP/1.1 500',9,3);return['status'=>$status,'raw'=>is_string($raw)?$raw:'','body'=>is_string($raw)?json_decode($raw,true):null];}
function marker_expect(int $status,array $result,string $what):array{if($result['status']!==$status)throw new RuntimeException("$what expected HTTP $status, got {$result['status']}: {$result['raw']}");echo "PASS $what returns HTTP $status\n";return is_array($result['body'])?$result['body']:[];}
function marker_session(PDO $pdo,string $phase='PHASE2'):int{$q=$pdo->prepare('INSERT INTO test_sessions(site_id,label,phase,design,tester_code,test_point) VALUES(?,?,?,?,?,?)');$q->execute(['pup','P7 marker scratch '.$phase.' '.bin2hex(random_bytes(3)),$phase,'A','P7','scratch']);return(int)$pdo->lastInsertId();}
function marker_packet(PDO $pdo,int $hiker,int $session,float $lat,float $lon,string $receivedAt,?float $accuracy=7.0,?int $satellites=6,bool $duplicate=false):int{$q=$pdo->prepare("INSERT INTO uplink_packets(hiker_node_id,site_id,sequence_number,latitude,longitude,gps_accuracy_m,satellite_count,battery_level,classification,session_id,received_at,is_duplicate,test_mode,is_demo) VALUES(:hiker,'pup',:sequence,:lat,:lon,:accuracy,:satellites,70,'UNCLASSIFIED',:session,:received,:duplicate,1,1)");$q->execute(['hiker'=>$hiker,'sequence'=>random_int(100000,2000000000),'lat'=>$lat,'lon'=>$lon,'accuracy'=>$accuracy,'satellites'=>$satellites,'session'=>$session,'received'=>$receivedAt,'duplicate'=>$duplicate?1:0]);return(int)$pdo->lastInsertId();}
try{
 $pdo=db();marker_expect(200,marker_call('POST','/api/settings/site',['site_id'=>'pup']),'select PUP site');
 marker_expect(401,marker_call('POST','/api/marker-checks',[],false),'marker-check write requires operator login and CSRF');
 marker_expect(403,marker_call('POST','/api/marker-checks',[],true,false),'marker-check write rejects an authenticated request without CSRF');
 $h=$pdo->prepare('SELECT id FROM hiker_nodes WHERE node_id=?');$h->execute(['H1']);$hiker=(int)$h->fetchColumn();if(!$hiker)throw new RuntimeException('Seeded scratch hiker H1 was not found.');
 $zone=active_zone($pdo,'pup');if(!$zone||empty($zone['rings'][0]))throw new RuntimeException('The PUP scratch safe-zone fixture has no outer ring.');$ring=$zone['rings'][0];$inside=['latitude'=>(float)$ring[0]['latitude'],'longitude'=>(float)$ring[0]['longitude']];$geometry=array_map(static fn($r)=>array_map(static fn($p)=>[(float)$p['latitude'],(float)$p['longitude']],$r),$zone['rings']);if(!point_in_polygon($inside['latitude'],$inside['longitude'],$geometry))throw new RuntimeException('The chosen outer-ring vertex did not classify inside.');$outside=null;for($step=1;$step<=200;$step++){ $candidate=['latitude'=>$inside['latitude']+$step*0.01,'longitude'=>$inside['longitude']];if(!point_in_polygon($candidate['latitude'],$candidate['longitude'],$geometry)){$outside=$candidate;break;}}if(!$outside)throw new RuntimeException('Could not derive an outside scratch point from the PUP zone.');
 // Average helper test: exact inclusive boundaries, session/node scoping, valid-fix rule, and duplicate exclusion.
 $avgSession=marker_session($pdo);$now=new DateTimeImmutable('now',new DateTimeZone('UTC'));$start=$now->modify('-60 seconds')->format('Y-m-d H:i:s');$end=$now->format('Y-m-d H:i:s');$before=$now->modify('-61 seconds')->format('Y-m-d H:i:s');$after=$now->modify('+1 second')->format('Y-m-d H:i:s');$p1=$inside;$p2=['latitude'=>$inside['latitude']+0.0002,'longitude'=>$inside['longitude']+0.0004];marker_packet($pdo,$hiker,$avgSession,$p1['latitude'],$p1['longitude'],$start);marker_packet($pdo,$hiker,$avgSession,$p2['latitude'],$p2['longitude'],$end);marker_packet($pdo,$hiker,$avgSession,$inside['latitude'],$inside['longitude'],$end,11.0,8);marker_packet($pdo,$hiker,$avgSession,$inside['latitude'],$inside['longitude'],$end,6.0,8,true);marker_packet($pdo,$hiker,$avgSession,$inside['latitude'],$inside['longitude'],$before);marker_packet($pdo,$hiker,$avgSession,$inside['latitude'],$inside['longitude'],$after);$avg=average_valid_fixes($pdo,$avgSession,'H1',$start,$end);marker_assert($avg['valid_fix_count']===2&&abs($avg['mean_latitude']-(($p1['latitude']+$p2['latitude'])/2))<0.00000001&&abs($avg['mean_longitude']-(($p1['longitude']+$p2['longitude'])/2))<0.00000001,'average helper includes both window boundaries, excludes invalid and duplicate fixes');marker_assert($avg['first_packet_at']===$start&&$avg['last_packet_at']===$end&&$avg['window_seconds']===60,'average helper returns first/last packet times and window duration');
 // No valid fixes means no row is stored.
 $zeroSession=marker_session($pdo);marker_packet($pdo,$hiker,$zeroSession,$inside['latitude'],$inside['longitude'],(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d H:i:s'),11.0,8);$beforeCount=(int)$pdo->query('SELECT COUNT(*) FROM marker_checks')->fetchColumn();$zero=marker_expect(422,marker_call('POST','/api/marker-checks',['session_id'=>$zeroSession,'node_id'=>'H1','gate_no'=>1,'marker_type'=>'INSIDE']),'zero-valid-fix marker check');$afterCount=(int)$pdo->query('SELECT COUNT(*) FROM marker_checks')->fetchColumn();marker_assert(str_contains($zero['error']??'','No valid GPS fixes')&&$afterCount===$beforeCount,'zero-valid-fix response is clear and stores nothing when only invalid fixes exist');
 // Inside/outside matches and non-blocking quality warnings.
 $insideSession=marker_session($pdo);$nowStr=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d H:i:s');marker_packet($pdo,$hiker,$insideSession,$inside['latitude'],$inside['longitude'],$nowStr);$insideCheck=marker_expect(201,marker_call('POST','/api/marker-checks',['session_id'=>$insideSession,'node_id'=>'H1','gate_no'=>1,'marker_type'=>'INSIDE','window_seconds'=>120]),'inside marker check');marker_assert($insideCheck['check']['classification']==='INSIDE'&&$insideCheck['check']['matches_intended']===true,'inside marker matches intended class');marker_assert(str_contains($insideCheck['check']['warning'],'Fewer than 10')&&$insideCheck['check']['valid_fix_count']===1,'few-fix warning is stored without blocking a check');
 $outsideSession=marker_session($pdo);marker_packet($pdo,$hiker,$outsideSession,$outside['latitude'],$outside['longitude'],$nowStr);$outsideCheck=marker_expect(201,marker_call('POST','/api/marker-checks',['session_id'=>$outsideSession,'node_id'=>'H1','gate_no'=>2,'marker_type'=>'OUTSIDE','window_seconds'=>120]),'outside marker check');marker_assert($outsideCheck['check']['classification']==='OUTSIDE'&&$outsideCheck['check']['matches_intended']===true,'outside marker matches intended class');
 $short=marker_expect(201,marker_call('POST','/api/marker-checks',['session_id'=>$insideSession,'node_id'=>'H1','gate_no'=>3,'marker_type'=>'INSIDE','window_seconds'=>30]),'short marker window');marker_assert(str_contains($short['check']['warning'],'under 100 seconds'),'under-100-second window warns without blocking');
 // A failed result followed by a later check of the same marker is counted as moved.
 $moveSession=marker_session($pdo);$oldPacket=marker_packet($pdo,$hiker,$moveSession,$outside['latitude'],$outside['longitude'],$nowStr);$failed=marker_expect(201,marker_call('POST','/api/marker-checks',['session_id'=>$moveSession,'node_id'=>'H1','gate_no'=>4,'marker_type'=>'INSIDE']),'failed marker check before moving');marker_assert($failed['check']['matches_intended']===false,'outside mean fails an INSIDE marker check');$old=$pdo->prepare('UPDATE uplink_packets SET received_at=UTC_TIMESTAMP()-INTERVAL 601 SECOND WHERE id=?');$old->execute([$oldPacket]);marker_packet($pdo,$hiker,$moveSession,$inside['latitude'],$inside['longitude'],(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d H:i:s'));$moved=marker_expect(201,marker_call('POST','/api/marker-checks',['session_id'=>$moveSession,'node_id'=>'H1','gate_no'=>4,'marker_type'=>'INSIDE']),'recheck moved marker');marker_assert($moved['check']['matches_intended']===true,'repeat check matches after the marker is moved');$list=marker_expect(200,marker_call('GET','/api/marker-checks?session_id='.$moveSession),'list checks with moved count');marker_assert(count($list['checks'])===2&&$list['checks'][0]['moved_count']===1&&$list['checks'][1]['moved_count']===1,'moved count is derived for failed checks followed by a later same-marker check');
 $phase3=marker_session($pdo,'PHASE3');marker_expect(409,marker_call('POST','/api/marker-checks',['session_id'=>$phase3,'node_id'=>'H1','gate_no'=>1,'marker_type'=>'INSIDE']),'non-PHASE2 marker check is rejected clearly');
 $csv=marker_call('GET','/api/export.csv?type=marker_checks&session_id='.$moveSession);marker_expect(200,$csv,'marker-check CSV export');$lines=array_values(array_filter(preg_split('/\r?\n/',$csv['raw']),static fn($line)=>$line!==''));$header=str_getcsv($lines[0]??'');$expected=['created_at','node_id','gate_no','marker_type','window_start','window_end','window_seconds','valid_fix_count','first_packet_at','last_packet_at','mean_latitude','mean_longitude','classification','intended_class','matches_intended','warning','moved_count','safe_zone_id'];marker_assert($header===$expected,'marker-check CSV columns follow the Settings table order');$matchIndex=array_search('matches_intended',$header,true);$classIndex=array_search('classification',$header,true);$intendedIndex=array_search('intended_class',$header,true);$csvChecks=array_map('str_getcsv',array_slice($lines,1));$failedCsv=array_values(array_filter($csvChecks,static fn($row)=>($row[$classIndex]??null)==='OUTSIDE'&&($row[$intendedIndex]??null)==='INSIDE'));$passedCsv=array_values(array_filter($csvChecks,static fn($row)=>($row[$classIndex]??null)==='INSIDE'&&($row[$intendedIndex]??null)==='INSIDE'));marker_assert(count($failedCsv)===1&&$failedCsv[0][$matchIndex]==='N'&&count($passedCsv)===1&&$passedCsv[0][$matchIndex]==='Y','marker-check CSV prints N for a failed check and Y for a passed check');
 $q=$pdo->prepare("SELECT COUNT(*) FROM operator_actions WHERE action_type='MARKER_CHECK_CREATED' AND site_id='pup'");$q->execute();marker_assert((int)$q->fetchColumn()>=5,'each saved marker check records an operator action');
}catch(Throwable $e){fwrite(STDERR,'FAIL '.$e->getMessage()."\n");exit(1);}
